/**
 * @summary Get all withdrawals (admin)
 */
export const getAdminGetWithdrawalsUrl = (
  params?: AdminGetWithdrawalsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/withdrawals?${stringifiedParams}`
    : `/api/admin/withdrawals`;
};

export const adminGetWithdrawals = async (
  params?: AdminGetWithdrawalsParams,
  options?: RequestInit,
): Promise<WithdrawalsResponse> => {
  return customFetch<WithdrawalsResponse>(getAdminGetWithdrawalsUrl(params), {
    ...options,
    method: "GET",
  });
};

